import java.util.*;
import java.io.*;

public class Main {
    static final long MOD = 1_000_000_007;

    static long modularInverse(long num) {
        long power = MOD - 2;
        long result = 1;
        long base = num;
        while (power > 0) {
            if ((power & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            power >>= 1;
        }
        return result;
    }

    public void run() {
        long[] factorials = new long[51];
        factorials[0] = 1;
        for (int i = 1; i < 51; i++) {
            factorials[i] = (factorials[i - 1] * i) % MOD;
        }
        long[][] combinations = new long[51][51];
        for (int i = 0; i <= 50; i++) {
            combinations[i][0] = 1;
        }
        for (int i = 1; i <= 50; i++) {
            for (int j = 1; j <= i; j++) {
                combinations[i][j] = (factorials[i] * modularInverse((factorials[j] * factorials[i - j]) % MOD)) % MOD;
            }
        }

        Scanner scanner = new Scanner(System.in);
        int total = scanner.nextInt();
        int maxCards = scanner.nextInt();
        int count50 = 0, count100 = 0;
        for (int i = 0; i < total; i++) {
            int val = scanner.nextInt();
            if (val == 100) count100++;
            else count50++;
        }

        Node[][][] graph = new Node[count50 + 1][count100 + 1][2];
        for (int i = 0; i <= count50; i++) {
            for (int j = 0; j <= count100; j++) {
                graph[i][j][0] = new Node(i, j, 0);
                graph[i][j][1] = new Node(i, j, 1);
            }
        }

        for (int i = 0; i <= count50; i++) {
            for (int j = 0; j <= count100; j++) {
                int max50Pick = Math.min(maxCards / 50, i);
                int max100Pick = Math.min(maxCards / 100, j);
                for (int x = max100Pick; x >= 0; x--) {
                    for (int y = Math.min(max50Pick, (maxCards - 100 * x) / 50); y >= 0; y--) {
                        if (x == 0 && y == 0) continue;
                        graph[i][j][0].s.add(graph[i - y][j - x][1]);
                        graph[i - y][j - x][1].s.add(graph[i][j][0]);
                    }
                }
            }
        }

        Queue<Node> q = new LinkedList<>();
        graph[count50][count100][0].n = 1;
        graph[count50][count100][0].am = 1;
        q.offer(graph[count50][count100][0]);

        while (!q.isEmpty()) {
            Node current = q.poll();
            for (Node neighbor : current.s) {
                if (neighbor.n == 0 || neighbor.n == current.n + 1) {
                    long p1 = combinations[current.b == 0 ? current.c50 : count50 - current.c50][Math.abs(current.c50 - neighbor.c50)];
                    long p2 = combinations[current.b == 0 ? current.c100 : count100 - current.c100][Math.abs(current.c100 - neighbor.c100)];
                    neighbor.am = (neighbor.am + (current.am * (p1 * p2) % MOD)) % MOD;
                    if (neighbor.n == 0) {
                        neighbor.n = current.n + 1;
                        q.offer(neighbor);
                    }
                }
            }
        }

        System.out.println((graph[0][0][1].n - 1) + "\n" + graph[0][0][1].am);
    }

    class Node {
        int c50, c100, b, n;
        long am;
        List<Node> s;
        Node(int c50, int c100, int b) {
            this.c50 = c50;
            this.c100 = c100;
            this.b = b;
            this.s = new ArrayList<>();
            this.n = 0;
            this.am = 0;
        }
    }

    public static void main(String[] args) {
        new Main().run();
    }
}
